CREATE VIEW [dbo].[v_DocTypes]
AS
SELECT D.Id, D.ClientId, D.QCPercent, D.IsReturnInfoSpecified, D.RetRcptPrefix, D.RetRcptFirstName, D.RetRcptMiddleName, D.RetRcptLastName, D.RetRcptSuffix, D.RetRcptPhone, D.RetRcptOrganization, D.RetRcptAddrOptionalLine1AboveStreet, D.RetRcptAddrOptionalLine2AboveStreet, D.RetRcptAddressStreet, D.RetRcptAddressAptOrSuiteOrOther, D.RetRcptAddrOptionalLine1BelowStreet, D.RetRcptAddrOptionalLine2BelowStreet, D.RetRcptAddressCity, D.RetRcptAddressState, D.RetRcptAddressZIP, D.RetRcptAddressCountry, D.ClientEmails, D.ClientContactNo, D.SupportEmails, D.SupportContactNo, D.IsActive, D.ModifiedOn, D.CreatedOn, D.CreatedBy, D.ModifiedBy, D.IsBRE, D.NoOfCopies, D.BREEnvelopeId, D.IsPrintReady, D.DocTypeName, D.PnSConfigId, PD.Id AS PnSConfigDetailId, PD.PrintSize, PD.ContentScalePercent, PD.PrintFormat, PD.ShippingCarrier, PD.ShippingServiceType, PD.ShippingAccountCode, PD.ShippingSpecialService, PD.MinPage, PD.MaxPage, PD.EnvelopeId, PD.IsFallBack, PD.BizdayCutOff, PD.BizdaySLAType, PD.BizdayTimeSpan, PD.SatCutOff, PD.SatSLAType, PD.SatTimeSpan, PD.SunCutOff, PD.SunSLAType, PD.SunTimeSpan
FROM AM.DocTypes D 
INNER JOIN Common.PnSConfig P ON D.PnSConfigId=P.Id
INNER JOIN Common.PnSConfigDetail PD ON P.Id=PD.PnSConfigId
